// German, Latin, Modern Greek and Russian inflections resolve to their
// dictionary forms (fushi/assets/transforms/de_extended.json, la_extended.json,
// el_extended.json and ru.json, generated by
// fushi/tool/gen_extended_transforms.dart, on top of the Yomitan ports de / la
// / el).
//
// Every table listed in manifest.json is loaded, exactly as the app does. Also
// pins the engine pieces these tables need:
//   - a second file of a language can add conditions (de_extended adds np and
//     vpp) without reusing the bits of the first file's conditions;
//   - the spelling variants ß / ss, æ / ae and ё / е, and Latin macrons.
//
// Usage: european_inflection_lookup_test <transforms dir>
#include <chrono>
#include <cstdio>
#include <filesystem>
#include <fstream>
#include <sstream>
#include <string>
#include <vector>

#include "fushidicts/deinflector.hpp"
#include "fushidicts/importer.hpp"
#include "fushidicts/lookup.hpp"
#include "fushidicts/query.hpp"
#include "zip_fixture.hpp"

namespace {

int g_fail = 0;

void fail(const std::string& msg) {
  std::fprintf(stderr, "FAIL: %s\n", msg.c_str());
  ++g_fail;
}

std::string read_file(const std::string& path) {
  std::ifstream in(path, std::ios::binary);
  if (!in) return {};
  std::ostringstream buf;
  buf << in.rdbuf();
  return buf.str();
}

// manifest.json is a flat array of language names.
std::vector<std::string> manifest_languages(const std::string& json) {
  std::vector<std::string> out;
  size_t i = 0;
  while ((i = json.find('"', i)) != std::string::npos) {
    const size_t end = json.find('"', i + 1);
    if (end == std::string::npos) break;
    out.push_back(json.substr(i + 1, end - i - 1));
    i = end + 1;
  }
  return out;
}

std::string dump(const std::vector<LookupResult>& results) {
  std::string s;
  for (const LookupResult& r : results) {
    s += "[" + r.term.expression + " <- " + r.matched;
    for (const TransformGroup& g : r.trace) s += " /" + g.name;
    s += "] ";
  }
  return s.empty() ? "(none)" : s;
}

// The hit must cover the whole query and must have gone through a transform,
// otherwise a query that happens to be a headword itself passes trivially.
bool has_whole_deinflected_hit(const std::vector<LookupResult>& results, const std::string& query,
                               const std::string& want_expression) {
  for (const LookupResult& r : results) {
    if (r.term.expression == want_expression && r.matched == query && !r.trace.empty()) return true;
  }
  return false;
}

void expect_lemma(Lookup& lk, const std::string& query, const std::string& want, const char* what) {
  std::vector<LookupResult> results = lk.lookup(query, 32);
  if (!has_whole_deinflected_hit(results, query, want)) {
    fail(std::string(what) + ": lookup(\"" + query + "\") did not deinflect to \"" + want + "\"; got " +
         dump(results));
  }
}

std::string term_row(const std::string& expr, const std::string& rules) {
  return "[\"" + expr + "\",\"\",\"\",\"" + rules + "\",0,[\"gloss of " + expr + "\"],0,\"\"]";
}

std::string import_yomitan(const char* label, const std::string& title, const std::vector<std::string>& rows,
                           const std::string& out_dir) {
  std::string bank = "[";
  for (size_t i = 0; i < rows.size(); i++) {
    if (i) bank += ",";
    bank += rows[i];
  }
  bank += "]";
  std::vector<fushi_test::ZipFile> files = {
      {"index.json", "{\"title\":\"" + title + "\",\"format\":3,\"revision\":\"1\"}"},
      {"term_bank_1.json", bank},
  };
  const std::string zip_path = fushi_test::write_zip(label, files);
  ImportResult r = dictionary_importer::import(zip_path, out_dir);
  if (!r.success) {
    fail(std::string("import ") + label + " failed: " + (r.errors.empty() ? "(no error)" : r.errors.front()));
    return {};
  }
  return out_dir + "/" + r.title;
}

// A hit on [want_expression] for the whole query, with or without a transform:
// spelling variants (ss for ß, е for ё) reach the headword without deinflecting.
void expect_lemma_matched_any(Lookup& lk, const std::string& query, const std::string& want_expression,
                              const char* what) {
  std::vector<LookupResult> results = lk.lookup(query, 32);
  for (const LookupResult& r : results) {
    if (r.term.expression == want_expression && r.matched == query) return;
  }
  fail(std::string(what) + ": lookup(\"" + query + "\") did not find \"" + want_expression + "\"; got " +
       dump(results));
}

}  // namespace

int main(int argc, char** argv) {
  if (argc < 2) {
    std::fprintf(stderr, "usage: %s <transforms dir>\n", argv[0]);
    return 2;
  }
  const std::string dir = argv[1];
  Deinflector d;
  for (const std::string& lang : manifest_languages(read_file(dir + "/manifest.json"))) {
    const std::string json = read_file(dir + "/" + lang + ".json");
    if (json.empty()) {
      fail("manifest lists " + lang + " but " + lang + ".json cannot be read");
      continue;
    }
    d.load_transforms_json(json);
  }
  if (g_fail) return 1;

  const std::string out_dir = fushi_test::temp_dir() + "/fushi_european_inflection_out";
  std::filesystem::remove_all(out_dir);

  std::vector<SimpleEntry> entries;
  for (const char* w : {
           // German
           "machen", "lernen", "arbeiten", "sammeln", "aufmachen", "studieren", "sehen", "verstehen", "anfangen",
           "gehen", "sein", "haben", "können", "Haus", "Kind", "Frau", "Mann", "Hand", "Mutter", "Garten", "alt",
           "schön", "gut", "groß", "dunkel", "Straße", "heißen",
           // Latin
           "amo", "moneo", "rego", "audio", "capio", "sum", "possum", "fero", "rosa", "dominus", "puer", "bellum",
           "natio", "rex", "corpus", "manus", "res", "bonus", "fortis", "pulcher",
           // Modern Greek
           "γράφω", "αγαπώ", "μπορώ", "έρχομαι", "είμαι", "λέω", "γυρίζω", "δρόμος", "θάλασσα", "παιδί", "καλός",
           // Russian
           "читать", "говорить", "гулять", "рисовать", "писать", "сказать", "видеть", "любить", "учиться", "идти",
           "уйти", "быть", "мочь", "поехать", "стол", "книга", "неделя", "окно", "здание", "дверь", "новый",
           "русский", "большой", "ёлка"}) {
    entries.push_back({w, std::string("definition of ") + w});
  }
  ImportResult r = dictionary_importer::write_simple_dict("EuropeanSimple", entries, out_dir);
  if (!r.success) {
    fail(r.errors.empty() ? "write_simple_dict failed" : r.errors.front());
    return 1;
  }
  DictionaryQuery q;
  q.add_term_dict(out_dir + "/" + r.title);
  Lookup lk(q, d);

  // ---- A) German -------------------------------------------------------------
  expect_lemma(lk, "machst", "machen", "A1 present 2sg");
  expect_lemma(lk, "lernte", "lernen", "A2 weak preterite");
  expect_lemma(lk, "arbeitete", "arbeiten", "A3 -ete preterite");
  expect_lemma(lk, "sammle", "sammeln", "A4 -eln verb");
  expect_lemma(lk, "gemacht", "machen", "A5 weak participle ge-...-t");
  expect_lemma(lk, "gemachten", "machen", "A6 participle with adjective ending");
  expect_lemma(lk, "aufgemacht", "aufmachen", "A7 separable participle");
  expect_lemma(lk, "aufzumachen", "aufmachen", "A8 zu-infinitive (Yomitan port still works)");
  expect_lemma(lk, "studiert", "studieren", "A9 -ieren participle");
  expect_lemma(lk, "sah", "sehen", "A10 strong preterite");
  expect_lemma(lk, "gesehen", "sehen", "A11 strong participle");
  expect_lemma(lk, "verstand", "verstehen", "A12 strong form of a prefixed verb");
  expect_lemma(lk, "anfing", "anfangen", "A13 strong form of a separable verb");
  expect_lemma(lk, "ging", "gehen", "A14 ging");
  expect_lemma(lk, "war", "sein", "A15 war");
  expect_lemma(lk, "hätte", "haben", "A16 Konjunktiv II");
  expect_lemma(lk, "konnte", "können", "A17 modal");
  expect_lemma(lk, "Häuser", "Haus", "A18 umlaut plural -er");
  expect_lemma(lk, "Kindern", "Kind", "A19 dative plural chained into plural");
  expect_lemma(lk, "Frauen", "Frau", "A20 plural -en");
  expect_lemma(lk, "Mannes", "Mann", "A21 genitive");
  expect_lemma(lk, "Hände", "Hand", "A22 umlaut plural -e");
  expect_lemma(lk, "Mütter", "Mutter", "A23 umlaut-only plural");
  expect_lemma(lk, "Gärten", "Garten", "A24 umlaut plural of -en noun");
  expect_lemma(lk, "älter", "alt", "A25 umlaut comparative");
  expect_lemma(lk, "ältesten", "alt", "A26 superlative with ending");
  expect_lemma(lk, "schönen", "schön", "A27 adjective ending");
  expect_lemma(lk, "besser", "gut", "A28 irregular comparative");
  expect_lemma(lk, "größte", "groß", "A29 umlaut superlative with ending");
  expect_lemma(lk, "dunkle", "dunkel", "A30 -el adjective drops its e");
  expect_lemma_matched_any(lk, "Strasse", "Straße", "A31 ss spelling finds ß headword");

  // ---- B) Latin --------------------------------------------------------------
  expect_lemma(lk, "amat", "amo", "B1 1st conj present");
  expect_lemma(lk, "amabant", "amo", "B2 imperfect");
  expect_lemma(lk, "amabit", "amo", "B3 future");
  expect_lemma(lk, "amavit", "amo", "B4 perfect");
  expect_lemma(lk, "amaverant", "amo", "B5 pluperfect");
  expect_lemma(lk, "amaretur", "amo", "B6 imperfect subjunctive passive");
  expect_lemma(lk, "amare", "amo", "B7 infinitive");
  expect_lemma(lk, "amatam", "amo", "B8 participle declined");
  expect_lemma(lk, "monebat", "moneo", "B9 2nd conj");
  expect_lemma(lk, "monuit", "moneo", "B10 2nd conj perfect");
  expect_lemma(lk, "regunt", "rego", "B11 3rd conj");
  expect_lemma(lk, "audiunt", "audio", "B12 4th conj");
  expect_lemma(lk, "audivit", "audio", "B13 4th conj perfect");
  expect_lemma(lk, "capiebat", "capio", "B14 3rd -io");
  expect_lemma(lk, "erat", "sum", "B15 sum");
  expect_lemma(lk, "potest", "possum", "B16 possum");
  expect_lemma(lk, "tulit", "fero", "B17 fero");
  expect_lemma(lk, "rosarum", "rosa", "B18 1st decl");
  expect_lemma(lk, "dominorum", "dominus", "B19 2nd decl");
  expect_lemma(lk, "pueri", "puer", "B20 -er noun");
  expect_lemma(lk, "bello", "bellum", "B21 neuter (Yomitan port)");
  expect_lemma(lk, "nationibus", "natio", "B22 3rd decl -tio");
  expect_lemma(lk, "regis", "rex", "B23 3rd decl -x");
  expect_lemma(lk, "corporis", "corpus", "B24 3rd decl -us -oris");
  expect_lemma(lk, "manuum", "manus", "B25 4th decl");
  expect_lemma(lk, "rerum", "res", "B26 5th decl");
  expect_lemma(lk, "bonorum", "bonus", "B27 adjective");
  expect_lemma(lk, "fortibus", "fortis", "B28 3rd decl adjective");
  expect_lemma(lk, "pulcherrima", "pulcher", "B29 superlative chained");
  expect_lemma(lk, "am\xC4\x81" "bat", "amo", "B30 macron is folded (amābat)");

  // ---- C) Modern Greek -------------------------------------------------------
  expect_lemma(lk, "γράφεις", "γράφω", "C1 present");
  expect_lemma(lk, "αγαπάς", "αγαπώ", "C2 contracted present");
  expect_lemma(lk, "αγαπούσε", "αγαπώ", "C3 contracted imperfect");
  expect_lemma(lk, "μπορείς", "μπορώ", "C4 -ώ verb");
  expect_lemma(lk, "έρχεται", "έρχομαι", "C5 mediopassive");
  expect_lemma(lk, "ήρθε", "έρχομαι", "C6 irregular aorist");
  expect_lemma(lk, "είναι", "είμαι", "C7 είμαι");
  expect_lemma(lk, "είπε", "λέω", "C8 λέω");
  expect_lemma(lk, "γυρίσει", "γυρίζω", "C9 aorist subjunctive");
  expect_lemma(lk, "δρόμους", "δρόμος", "C10 noun -ος");
  expect_lemma(lk, "θάλασσες", "θάλασσα", "C11 noun -α");
  expect_lemma(lk, "παιδιά", "παιδί", "C12 noun -ι");
  expect_lemma(lk, "καλή", "καλός", "C13 adjective");

  // ---- D) Russian ------------------------------------------------------------
  expect_lemma(lk, "читаю", "читать", "D1 present 1sg");
  expect_lemma(lk, "читали", "читать", "D2 past");
  expect_lemma(lk, "говорит", "говорить", "D3 2nd conj");
  expect_lemma(lk, "гуляет", "гулять", "D4 -ять");
  expect_lemma(lk, "рисует", "рисовать", "D5 -овать");
  expect_lemma(lk, "пишу", "писать", "D6 с -> ш");
  expect_lemma(lk, "скажет", "сказать", "D7 з -> ж");
  expect_lemma(lk, "вижу", "видеть", "D8 д -> ж");
  expect_lemma(lk, "люблю", "любить", "D9 epenthetic л");
  expect_lemma(lk, "учусь", "учиться", "D10 reflexive -сь");
  expect_lemma(lk, "учится", "учиться", "D11 reflexive -ся");
  expect_lemma(lk, "идёт", "идти", "D12 идти");
  expect_lemma(lk, "идет", "идти", "D13 е spelling of ё (yoToE)");
  expect_lemma(lk, "ушла", "уйти", "D14 prefixed идти past");
  expect_lemma(lk, "будет", "быть", "D15 быть");
  expect_lemma(lk, "может", "мочь", "D16 мочь");
  expect_lemma(lk, "поедем", "поехать", "D17 prefixed ехать");
  expect_lemma(lk, "столами", "стол", "D18 masc noun");
  expect_lemma(lk, "книги", "книга", "D19 fem noun");
  expect_lemma(lk, "неделю", "неделя", "D20 fem -я");
  expect_lemma(lk, "окна", "окно", "D21 neuter -о");
  expect_lemma(lk, "здании", "здание", "D22 neuter -ие");
  expect_lemma(lk, "дверью", "дверь", "D23 fem -ь");
  expect_lemma(lk, "новая", "новый", "D24 adjective");
  expect_lemma(lk, "русского", "русский", "D25 -кий adjective");
  expect_lemma(lk, "больше", "большой", "D26 irregular comparative");
  expect_lemma(lk, "читающая", "читать", "D27 participle declined");
  expect_lemma_matched_any(lk, "елка", "ёлка", "D28 е spelling finds ё headword");

  // ---- E) the other languages are unaffected ---------------------------------
  {
    std::vector<SimpleEntry> control = {{"walk", "w"}, {"hablar", "h"}, {"falar", "f"}};
    ImportResult rc = dictionary_importer::write_simple_dict("EuropeanControl", control, out_dir);
    if (!rc.success) return 1;
    DictionaryQuery qc;
    qc.add_term_dict(out_dir + "/" + rc.title);
    Lookup lc(qc, d);
    expect_lemma(lc, "walked", "walk", "E1 English");
    expect_lemma(lc, "hablamos", "hablar", "E2 Spanish");
    expect_lemma(lc, "falamos", "falar", "E3 Portuguese");
  }

  const auto start = std::chrono::steady_clock::now();
  for (int i = 0; i < 50; i++) {
    lk.lookup("Die Kinder spielten im Garten", 32);
    lk.lookup("он читал интересную книгу", 32);
  }
  const double ms =
      std::chrono::duration<double, std::milli>(std::chrono::steady_clock::now() - start).count() / 100.0;
  std::printf("average lookup: %.3f ms\n", ms);
  if (ms > 5.0) fail("lookup got slow: " + std::to_string(ms) + " ms per call");

  std::filesystem::remove_all(out_dir);
  if (g_fail) {
    std::fprintf(stderr, "%d failure(s)\n", g_fail);
    return 1;
  }
  std::printf("european_inflection_lookup_test: all passed\n");
  return 0;
}
